#!/usr/bin/env node
/**
 * Point the generated `android/app/build.gradle` at a real release keystore.
 *
 * Why this exists: `android/` is git-ignored (apps/mobile/.gitignore) and is
 * regenerated by `expo prebuild` on every build. Expo's stock template signs
 * the *release* variant with the well-known Android **debug** keystore, so a
 * build straight out of `prebuild` produces an APK that anyone can
 * impersonate. Editing `build.gradle` by hand is not an option either — the
 * file does not exist in the repo.
 *
 * So the signing config is applied by this script, which CI runs after
 * `expo prebuild` and before `gradlew assembleRelease`. It is deliberately
 * strict: every anchor is asserted, and it refuses to run when the RELEASE_*
 * environment variables are missing. A silent no-op here would ship a
 * debug-signed APK that still passes `apksigner verify`, which is exactly the
 * failure this script is meant to prevent.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const GRADLE_PATH = resolve(here, "../android/app/build.gradle");

const REQUIRED_ENV = [
  "RELEASE_STORE_FILE",
  "RELEASE_STORE_PASSWORD",
  "RELEASE_KEY_ALIAS",
  "RELEASE_KEY_PASSWORD",
];

function fail(message) {
  console.error(`configure-release-signing: ${message}`);
  process.exit(1);
}

const missing = REQUIRED_ENV.filter((name) => !process.env[name]?.trim());
if (missing.length > 0) {
  fail(
    `missing required environment variable(s): ${missing.join(", ")}. ` +
      `These carry the release keystore path and credentials and must be ` +
      `injected from CI secrets — refusing to fall back to the debug keystore.`,
  );
}

let gradle;
try {
  gradle = readFileSync(GRADLE_PATH, "utf8");
} catch (error) {
  fail(
    `cannot read ${GRADLE_PATH} (${error.code ?? error.message}). ` +
      `Run "expo prebuild --platform android" first.`,
  );
}

const PATCH_MARKER = 'storeFile file(System.getenv("RELEASE_STORE_FILE"))';
if (gradle.includes(PATCH_MARKER)) {
  fail(
    "build.gradle is already patched for release signing — refusing to patch " +
      "twice. If this is unexpected, run `expo prebuild --clean --platform android` " +
      "to regenerate android/ from the template.",
  );
}

// --- 1. Add a `release` signing config next to the template's `debug` one ---
const DEBUG_SIGNING_BLOCK = `    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }`;

const DEBUG_AND_RELEASE_SIGNING_BLOCK = `    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
        // Credentials come from the environment (CI secrets), never from this
        // file — the generated android/ tree is git-ignored and must stay
        // secret-free. See apps/mobile/scripts/configure-release-signing.mjs.
        release {
            storeFile file(System.getenv("RELEASE_STORE_FILE"))
            storePassword System.getenv("RELEASE_STORE_PASSWORD")
            keyAlias System.getenv("RELEASE_KEY_ALIAS")
            keyPassword System.getenv("RELEASE_KEY_PASSWORD")
        }
    }`;

if (!gradle.includes(DEBUG_SIGNING_BLOCK)) {
  fail(
    "could not find the expo template's `signingConfigs { debug { ... } }` " +
      "block in build.gradle. The Expo template changed — update this script " +
      "instead of guessing at the new shape.",
  );
}
gradle = gradle.replace(DEBUG_SIGNING_BLOCK, DEBUG_AND_RELEASE_SIGNING_BLOCK);

// --- 2. Repoint the release build type at it ------------------------------
const RELEASE_USES_DEBUG = `            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug`;

const RELEASE_USES_RELEASE = `            // Signed with the release keystore injected via the RELEASE_*
            // environment variables (see scripts/configure-release-signing.mjs).
            signingConfig signingConfigs.release`;

if (!gradle.includes(RELEASE_USES_DEBUG)) {
  fail(
    "could not find the release build type's `signingConfig signingConfigs.debug` " +
      "line (with its React Native caution comment). Either the template " +
      "changed or prebuild emitted a different shape — update this script.",
  );
}
gradle = gradle.replace(RELEASE_USES_DEBUG, RELEASE_USES_RELEASE);

// --- 3. Post-conditions ---------------------------------------------------
const checks = [
  ["release signingConfig declared", "release {\n            storeFile file(System.getenv(\"RELEASE_STORE_FILE\"))"],
  ["release build type repointed", "signingConfig signingConfigs.release"],
];
for (const [label, needle] of checks) {
  if (!gradle.includes(needle)) {
    fail(`post-condition failed after patching: ${label}`);
  }
}
if (gradle.includes("            signingConfig signingConfigs.debug\n            def enableShrinkResources")) {
  fail(
    "post-condition failed: the release build type still resolves to " +
      "signingConfigs.debug",
  );
}

writeFileSync(GRADLE_PATH, gradle);
console.log(
  "configure-release-signing: release build type now signs with " +
    "signingConfigs.release (keystore from RELEASE_STORE_FILE).",
);
